local items = require "wa.items"
local skills = require "wa.skills"
local jobs = require "wa.jobs"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local MC_PUSHCART = skills.id "MC_PUSHCART"
local CART_FREE_TICKET = items.id "Cart_Free_Ticket"
local RESRVPTS = variables.character_integer "resrvpts"

return function(player, conversation, npc, ...)
  local rental_fee = 0
  local args = table.pack(...)
  if (jobs.first_job(player.job) ~= jobs.merchant) then
    conversation:say("[Kafra Employee]", "I'm sorry, but the", "Pushcart rental service")
    do
      conversation:say("is only available to Merchant classes.")
    end
    do return 1 end
  elseif ((player.cart ~= nil and 1 or 0) == 1) then
    conversation:say("[Kafra Employee]", "You already have", "a Pushcart equipped.", "Unfortunately, we can't", "rent more than one to", "each customer at a time.")
    do return 1 end
  elseif (player:get_skill_level(MC_PUSHCART) == 0) then
    conversation:say("[Kafra Employee]", "You can only rent a cart after learning the \"Push Cart\" skill.")
    do return 1 end
  end
  if ((player:count_item(CART_FREE_TICKET) > 0) and (R.arg(args, 0) ~= 2)) then
    player:take_item(CART_FREE_TICKET, 1)
  else
    rental_fee = (R.arg(args, 1) or 0)
    conversation:say("[Kafra Employee]", "The Pushcart rental", "fee is " .. rental_fee .. " zeny. Would", "you like to rent a Pushcart?")
    conversation:wait_for_next()
    if (conversation:choose("Rent a Pushcart.", "Cancel") == 2) then
      do return 0 end
    end
    if (player.zeny < rental_fee) then
      conversation:say("[Kafra Employee]", "I'm sorry, but you", "don't have enough", "zeny to pay the Pushcart", "rental fee of " .. rental_fee .. " zeny.")
      do return 1 end
    end
    player:pay_zeny(rental_fee)
    RESRVPTS:add(player, 48)
  end
  player:set_cart(1)
  do return 1 end
end
